<?php
namespace App\Controllers;
use App\Core\{Controller,Request,Auth,Csrf,Uploader}; use App\Models\{Product,Order,Vendor};
class VendorController extends Controller { public function dashboard(){return $this->view('vendor/dashboard',['products'=>(new Product)->all(),'orders'=>(new Order)->all()]);} public function products(){return $this->view('vendor/products',['products'=>(new Product)->all()]);} public function saveProduct(Request $r){Csrf::check($r->get('_csrf')); $image=!empty($r->files['image']['name'])?Uploader::image($r->files['image']):null; (new Product)->create(['vendor_id'=>1,'category_id'=>(int)$r->get('category_id',1),'name'=>$r->get('name'),'slug'=>strtolower(preg_replace('/[^a-z0-9]+/','-',$r->get('name'))),'description'=>$r->get('description'),'price'=>$r->get('price'),'sale_price'=>$r->get('sale_price',0),'sku'=>$r->get('sku'),'stock'=>$r->get('stock',0),'image'=>$image,'status'=>'active','meta_title'=>$r->get('meta_title'),'meta_description'=>$r->get('meta_description')]); return $this->redirect('/vendor/products');} }
